// Al final de handleSubmit, después de crear la orden y mostrar toast:
const result = await createOrder(order);
if (result.success) {
  toast({
    title: "Order placed successfully!",
    description: order.orderMode === "takeaway"
      ? `Your order #${result.order.id} will be ready for pickup soon.`
      : `Your order #${result.order.id} is being prepared for delivery.`,
  });
  router.push("/track");
}